  "Send {command} to the Space app in a direct message in {where} before {time}. The code works once.": "Στείλε {command} στην εφαρμογή Space με απευθείας μήνυμα στο {where} πριν από τις {time}. Ο κωδικός δουλεύει μία φορά.",
  "or": "ή",
  "Message your Dots from Slack or Teams. Start a message with a Dot's name, for example \"Orbit: summarize my day\". In shared conversations, answers come to you directly unless you write \"reply here\" in the thread. Approvals are always decided in Space.": "Στείλε μήνυμα στα Dots σου από το Slack ή το Teams. Ξεκίνα το μήνυμα με το όνομα ενός Dot, για παράδειγμα «Orbit: σύνοψη της μέρας μου». Στις κοινές συζητήσεις οι απαντήσεις έρχονται σε σένα απευθείας, εκτός αν γράψεις \"reply here\" στο νήμα. Οι εγκρίσεις αποφασίζονται πάντα στο Space.",
  "Linked {when} · {count} threads": "Συνδέθηκε {when} · {count} νήματα",
