  "Loading connections…": "Φορτώνουν οι συνδέσεις…",
  "Dots read and draft email and check calendars only through accounts you connect here. Sending email and creating events wait for your approval unless you turn that off in Settings → Dots.": "Τα Dots διαβάζουν και συντάσσουν email και ελέγχουν ημερολόγια μόνο μέσα από λογαριασμούς που συνδέεις εδώ. Η αποστολή email και η δημιουργία συμβάντων περιμένουν την έγκρισή σου, εκτός αν το απενεργοποιήσεις στις Ρυθμίσεις → Dots.",
