  "Google says “Access blocked”?": "Η Google δείχνει “Access blocked”;",
  "While the server's Google Cloud app is in Testing, only its test users can connect. In Google Cloud Console open Google Auth Platform → Audience and add the account under Test users, or publish the app. Enable the Gmail API and Google Calendar API for the same project. Access granted in Testing ends after seven days; Space then asks you to reconnect.": "Όσο η εφαρμογή Google Cloud του διακομιστή είναι σε λειτουργία Testing, μπορούν να συνδεθούν μόνο οι δοκιμαστικοί χρήστες της. Στο Google Cloud Console άνοιξε το Google Auth Platform → Audience και πρόσθεσε τον λογαριασμό στους Test users ή δημοσίευσε την εφαρμογή. Ενεργοποίησε το Gmail API και το Google Calendar API για το ίδιο project. Η πρόσβαση που δίνεται σε λειτουργία Testing λήγει μετά από επτά ημέρες· τότε το Space σου ζητά να συνδεθείς ξανά.",
