  "Confirming your request…": "Επιβεβαιώνεται το αίτημά σου…",
  "Request confirmation is missing. Check the saved request before sending anything else. This uses the same submission and does not start a second task.": "Λείπει η επιβεβαίωση του αιτήματος. Έλεγξε το αποθηκευμένο αίτημα πριν στείλεις οτιδήποτε άλλο. Αυτό χρησιμοποιεί την ίδια υποβολή και δεν ξεκινά δεύτερη εργασία.",
