  "Session status unavailable. Reconnect before sending.": "Η κατάσταση της συνεδρίας δεν είναι διαθέσιμη. Επανασύνδεση πριν από την αποστολή.",
  "Finish importing files before sending": "Ολοκλήρωσε την εισαγωγή αρχείων πριν από την αποστολή",
