  "Loading permissions…": "Φορτώνουν τα δικαιώματα…",
  "Result check saved for your next message.": "Ο έλεγχος αποτελέσματος αποθηκεύτηκε για το επόμενο μήνυμά σου.",
  "Result check removed.": "Ο έλεγχος αποτελέσματος αφαιρέθηκε.",
  "Session selection is unconfirmed. Reconnect before sending.": "Η επιλογή συνεδρίας δεν επιβεβαιώθηκε. Επανασύνδεση πριν από την αποστολή.",
  "Dot selection failed.": "Η επιλογή Dot απέτυχε.",
  "Check the next result": "Έλεγξε το επόμενο αποτέλεσμα",
  "Compare the final answer with the text you expect. Only this check is assessed; it does not certify the whole answer.": "Σύγκρινε την τελική απάντηση με το κείμενο που περιμένεις. Αξιολογείται μόνο αυτός ο έλεγχος· δεν πιστοποιεί ολόκληρη την απάντηση.",
  "Expected answer": "Αναμενόμενη απάντηση",
  "Leading and trailing whitespace in the answer is ignored. Write the task instructions in your message.": "Τα κενά στην αρχή και στο τέλος της απάντησης αγνοούνται. Γράψε τις οδηγίες της εργασίας στο μήνυμά σου.",
  "Remove check": "Αφαίρεση ελέγχου",
  "Save check": "Αποθήκευση ελέγχου",
  "Open a Dot's Tools view and connect again.": "Άνοιξε την προβολή Εργαλείων ενός Dot και συνδέσου ξανά.",
  "Account connected. Your Dots can use it from now on. Each email and event waits for your approval unless you turn that off in Settings → Dots.": "Ο λογαριασμός συνδέθηκε. Τα Dots σου μπορούν να τον χρησιμοποιούν από τώρα. Κάθε email και συμβάν περιμένει την έγκρισή σου, εκτός αν το απενεργοποιήσεις στις Ρυθμίσεις → Dots.",
  "The account was not connected: the sign-in was cancelled or the provider refused it.": "Ο λογαριασμός δεν συνδέθηκε: η σύνδεση ακυρώθηκε ή ο πάροχος την απέρριψε.",
  "The sign-in took too long or was started in another tab.": "Η σύνδεση άργησε πολύ ή ξεκίνησε σε άλλη καρτέλα.",
  "The sign-in finished in a different Space session than the one that started it. Connect again from this window.": "Η σύνδεση ολοκληρώθηκε σε διαφορετική συνεδρία Space από αυτήν που την ξεκίνησε. Συνδέσου ξανά από αυτό το παράθυρο.",
  "The sign-in expired before it finished.": "Η σύνδεση έληξε πριν ολοκληρωθεί.",
  "The account has no verified email address, so it was not connected.": "Ο λογαριασμός δεν έχει επαληθευμένη διεύθυνση email, γι' αυτό δεν συνδέθηκε.",
  "The provider did not grant lasting access. Remove Space's access in your account settings, then connect again from a Dot's Tools view.": "Ο πάροχος δεν έδωσε διαρκή πρόσβαση. Αφαίρεσε την πρόσβαση του Space στις ρυθμίσεις του λογαριασμού σου και μετά συνδέσου ξανά από την προβολή Εργαλείων ενός Dot.",
  "That provider is not configured on this server.": "Αυτός ο πάροχος δεν έχει ρυθμιστεί σε αυτόν τον διακομιστή.",
  "Open Mail Copilot Setup → Accounts and choose Allow full Gmail access again.": "Άνοιξε τη Ρύθμιση του Mail Copilot → Λογαριασμοί και διάλεξε ξανά «Allow full Gmail access».",
  "Full Gmail access allowed. Mail Copilot now shows this account's mail and can reply, label and archive for you under your autonomy setting.": "Επιτράπηκε πλήρης πρόσβαση στο Gmail. Το Mail Copilot δείχνει πλέον τα μηνύματα αυτού του λογαριασμού και μπορεί να απαντά, να βάζει ετικέτες και να αρχειοθετεί για σένα σύμφωνα με τη ρύθμιση αυτονομίας σου.",
  "Gmail access was not allowed: the sign-in was cancelled or Google refused it.": "Η πρόσβαση στο Gmail δεν επιτράπηκε: η σύνδεση ακυρώθηκε ή το Google την απέρριψε.",
  "Google did not grant lasting access. Remove Space's access in your Google Account settings, then {retry}": "Το Google δεν έδωσε διαρκή πρόσβαση. Αφαίρεσε την πρόσβαση του Space στις ρυθμίσεις του Λογαριασμού Google σου και μετά {retry}",
  "Gmail access could not be allowed.": "Η πρόσβαση στο Gmail δεν μπόρεσε να επιτραπεί.",
