  "Mission status is unavailable.": "Η κατάσταση της αποστολής δεν είναι διαθέσιμη.",
  "Mission request failed. Refresh before retrying.": "Το αίτημα αποστολής απέτυχε. Ανανέωσε πριν ξαναδοκιμάσεις.",
  "Select a room before using missions.": "Διάλεξε ένα δωμάτιο πριν χρησιμοποιήσεις αποστολές.",
