  "Mission acknowledgement is missing. Refresh server status before retrying.": "Λείπει η επιβεβαίωση της αποστολής. Ανανέωσε την κατάσταση του διακομιστή πριν ξαναδοκιμάσεις.",
  "Mission acknowledgement belongs to another mission. Refresh before retrying.": "Η επιβεβαίωση ανήκει σε άλλη αποστολή. Ανανέωσε πριν ξαναδοκιμάσεις.",
  "Provide a mission goal of 1–4000 characters.": "Δώσε στόχο αποστολής 1–4000 χαρακτήρων.",
