  "Inventory {time} · {packages} packages · {pending} security updates waiting · {findings} open findings": "Καταγραφή {time} · {packages} πακέτα · {pending} ενημερώσεις ασφαλείας σε αναμονή · {findings} ανοιχτά ευρήματα",
