  "Resize the Security Copilot rail": "Άλλαξε το πλάτος της πλαϊνής στήλης του Security Copilot",
  "The Security Copilot could not be loaded.": "Το Security Copilot δεν φορτώθηκε.",
  "On: backed-up package, service, config, WAF, container and code fixes run on their own. Off (Assist): every change waits for your approval. Reboots, restarts that end your sessions, deletes and free-form commands always wait for you.": "Ενεργό: οι διορθώσεις πακέτων, υπηρεσιών, ρυθμίσεων, WAF, containers και κώδικα, με αντίγραφο ασφαλείας, τρέχουν μόνες τους. Ανενεργό (Υποβοήθηση): κάθε αλλαγή περιμένει την έγκρισή σου. Οι επανεκκινήσεις, οι επανεκκινήσεις που τερματίζουν τις συνεδρίες σου, οι διαγραφές και οι ελεύθερες εντολές περιμένουν πάντα εσένα.",
  "The copilot takes no new work and makes no change while paused.": "Το copilot δεν παίρνει νέα δουλειά και δεν κάνει αλλαγές όσο είναι σε παύση.",
  "A stable hotfix of SpaceApp's own code goes ahead without you only when Nous may approve security hotfixes (Settings → Assistants & AI → Nous).": "Ένα hotfix στο stable για τον ίδιο τον κώδικα του SpaceApp προχωρά χωρίς εσένα μόνο όταν ο Nous μπορεί να εγκρίνει hotfix ασφαλείας (Ρυθμίσεις → Βοηθοί & AI → Nous).",
  "Hosts the copilot works on": "Hosts στα οποία δουλεύει το copilot",
  "The copilot discovers the hosts on its first run.": "Το copilot ανακαλύπτει τα hosts στην πρώτη του εκτέλεση.",
  "Public addresses": "Δημόσιες διευθύνσεις",
  "Checked against what the internet sees (Shodan InternetDB) every 30 minutes.": "Ελέγχονται με ό,τι βλέπει το διαδίκτυο (Shodan InternetDB) κάθε 30 λεπτά.",
  "Remove": "Αφαίρεση",
