  "Critical findings, changes waiting for your approval and questions. Exploited findings and failed fixes always alert you.": "Κρίσιμα ευρήματα, αλλαγές που περιμένουν την έγκρισή σου και ερωτήσεις. Τα ευρήματα σε εκμετάλλευση και οι αποτυχημένες διορθώσεις σε ειδοποιούν πάντα.",
  "Fixed notifications": "Ειδοποιήσεις διορθώσεων",
