  "Switching the security engineer or its account restarts this pane's CLI session; findings, actions and memory stay. Claude Code is recommended.": "Η αλλαγή του μηχανικού ασφαλείας ή του λογαριασμού του επανεκκινεί τη συνεδρία CLI αυτού του pane· τα ευρήματα, οι ενέργειες και η μνήμη μένουν. Το Claude Code προτείνεται.",
  "New Security Copilot panes open with {agent} ({account} account) without asking.": "Τα νέα panes Security Copilot ανοίγουν με {agent} (λογαριασμός {account}) χωρίς να ρωτήσουν.",
