  "While the server's Google Cloud app is in Testing, only its test users can allow access. In Google Cloud Console open Google Auth Platform → Audience and add the account under Test users, or publish the app. Enable the Gmail API and Google Calendar API for the same project. Access allowed in Testing ends after seven days; Job Copilot then asks you to allow it again.": "Όσο η εφαρμογή Google Cloud του διακομιστή είναι σε Testing, μόνο οι test users της μπορούν να επιτρέψουν πρόσβαση. Στο Google Cloud Console άνοιξε Google Auth Platform → Audience και πρόσθεσε τον λογαριασμό στους Test users ή δημοσίευσε την εφαρμογή. Ενεργοποίησε το Gmail API και το Google Calendar API για το ίδιο project. Η πρόσβαση που επιτρέπεται σε Testing λήγει μετά από επτά ημέρες· τότε το Job Copilot σε ρωτά να την επιτρέψεις ξανά.",
