  "Under Rules autonomy the copilot acts alone only where an approved rule matches. When you handle a sender's mail the same way three times or more on an account, the rule is learned and approved on its own; retire it whenever you like.": "Στην αυτονομία Κανόνων το copilot ενεργεί μόνο του όπου ταιριάζει ένας εγκεκριμένος κανόνας. Όταν χειρίζεσαι τα μηνύματα ενός αποστολέα με τον ίδιο τρόπο τρεις ή περισσότερες φορές σε έναν λογαριασμό, ο κανόνας μαθαίνεται και εγκρίνεται αυτόματα· απόσυρέ τον όποτε θέλεις.",
