  "Space Gateway (pooled): every {agent} pane uses the gateway's ChatGPT accounts.": "Space Gateway (κοινή δεξαμενή): κάθε pane {agent} χρησιμοποιεί τους λογαριασμούς ChatGPT του gateway.",
  "The account the agent's CLI starts on. Space Gateway (pooled) spreads the work over the gateway's accounts.": "Ο λογαριασμός με τον οποίο ξεκινά το CLI του πράκτορα. Το Space Gateway (κοινή δεξαμενή) μοιράζει τη δουλειά στους λογαριασμούς του gateway.",
