  "Give App Studio a brief in Activity. Its agent builds the app and shows every screen here on Android and iPhone.": "Δώσε στο App Studio μια εντολή στη Δραστηριότητα. Ο πράκτοράς του χτίζει την εφαρμογή και δείχνει εδώ κάθε οθόνη σε Android και iPhone.",
