  "Android": "Android",
  "iPhone": "iPhone",
  "Answer sent to the app builder.": "Η απάντηση στάλθηκε στον δημιουργό της εφαρμογής.",
  "Brief sent. The app builder starts on it at its next free moment.": "Η εντολή στάλθηκε. Ο δημιουργός της εφαρμογής ξεκινά να τη δουλεύει στην επόμενη ελεύθερη στιγμή του.",
  "Ask App Studio to build or change something": "Ζήτα από το App Studio να φτιάξει ή να αλλάξει κάτι",
  "e.g. A habit tracker with a home list, an add screen and dark mode": "π.χ. Ένα πρόγραμμα παρακολούθησης συνηθειών με λίστα αρχικής, οθόνη προσθήκης και σκούρο θέμα",
  "APK build asked for. The app builder starts on it at its next free moment.": "Ζητήθηκε κατασκευή APK. Ο δημιουργός της εφαρμογής ξεκινά να τη δουλεύει στην επόμενη ελεύθερη στιγμή του.",
  "Build APK": "Κατασκευή APK",
