  "Publishes on its own judgement within each channel's cap and limit; you follow along in Activity.": "Δημοσιεύει με δική του κρίση μέσα στο ανώτατο όριο και το όριο δημοσιεύσεων κάθε καναλιού· παρακολουθείς από τη Δραστηριότητα.",
