  "Save a site with the Google account it opens with. One click opens it in the pane browser, signed in, and the copilot can open it too.": "Αποθήκευσε έναν ιστότοπο μαζί με τον λογαριασμό Google που ανοίγει. Ένα κλικ τον ανοίγει στον περιηγητή του pane, συνδεδεμένο, και μπορεί να τον ανοίξει και ο copilot.",
  "Channels": "Κανάλια",
  "Where the copilot promotes SpaceApp, always on your own accounts. Each channel has a highest autonomy and a publishing limit that hold whatever the pane's autonomy is. Log in once per channel in this pane's browser; the copilot hands you the browser whenever a site asks for a login, a code or a CAPTCHA.": "Εδώ ο copilot προωθεί το SpaceApp, πάντα στους δικούς σου λογαριασμούς. Κάθε κανάλι έχει μια ανώτατη αυτονομία και ένα όριο δημοσιεύσεων που ισχύουν όποια αυτονομία κι αν έχει το pane. Συνδέσου μία φορά σε κάθε κανάλι στον περιηγητή αυτού του pane· ο copilot σού δίνει τον περιηγητή όποτε ένας ιστότοπος ζητά σύνδεση, κωδικό ή CAPTCHA.",
  "Acts as {level} here": "Εδώ λειτουργεί σε λειτουργία {level}",
