  "The copilot never votes, likes or asks for upvotes, never messages people in bulk and only uses your own accounts. Login, two-step codes and CAPTCHAs are handed to you.": "Ο copilot δεν ψηφίζει, δεν κάνει like και δεν ζητά upvotes, δεν στέλνει μαζικά μηνύματα σε κόσμο και χρησιμοποιεί μόνο τους δικούς σου λογαριασμούς. Η σύνδεση, οι κωδικοί δύο βημάτων και τα CAPTCHA περνούν σε σένα.",
  "The copilot opens no new work item while paused, and approved posts wait; the browser keeps working.": "Σε παύση ο copilot δεν ανοίγει νέα εργασία και οι εγκεκριμένες αναρτήσεις περιμένουν· ο περιηγητής συνεχίζει να δουλεύει.",
