  "{count} of {total} panes visible.": "{count} από {total} panes ορατά.",
  "Desktop widgets visibility settings": "Ρυθμίσεις ορατότητας των widgets επιφάνειας εργασίας",
  "Desktop widgets": "Widgets επιφάνειας εργασίας",
  "Choose which desktop widgets appear in your tools menu and workspace ({count} enabled).": "Διάλεξε ποια widgets επιφάνειας εργασίας εμφανίζονται στο μενού εργαλείων και στον χώρο εργασίας σου ({count} ενεργά).",
  "Reset widget visibility to defaults": "Επαναφορά της ορατότητας των widgets στις προεπιλογές",
  "Widget toggles": "Διακόπτες widgets",
  "Toggle {label} visibility": "Εναλλαγή ορατότητας του {label}",
  "Workspace docks visibility settings": "Ρυθμίσεις ορατότητας των docks του χώρου εργασίας",
  "Workspace docks": "Docks χώρου εργασίας",
  "Choose which docks appear in your workspace navigation and toolbar. Drag a dock to change its place.": "Διάλεξε ποια docks εμφανίζονται στην πλοήγηση και στη γραμμή εργαλείων του χώρου εργασίας σου. Σύρε ένα dock για να αλλάξεις τη θέση του.",
  "Reset dock visibility and order to defaults": "Επαναφορά της ορατότητας και της σειράς των docks στις προεπιλογές",
  "Dock toggles": "Διακόπτες docks",
  "Always visible to ensure you never lose access to workspace settings.": "Πάντα ορατό ώστε να μη χάνεις ποτέ την πρόσβαση στις ρυθμίσεις του χώρου εργασίας.",
  "Always visible. Settings dock cannot be hidden.": "Πάντα ορατό. Το dock των Ρυθμίσεων δεν μπορεί να κρυφτεί.",
  "Always visible": "Πάντα ορατό",
  "Default hidden: required plugin is not active. Cannot be enabled until it is activated.": "Κρυμμένο από προεπιλογή: το απαιτούμενο plugin δεν είναι ενεργό. Δεν μπορεί να ενεργοποιηθεί μέχρι να ενεργοποιηθεί εκείνο.",
